// Templates that turn hand-written synthetic facts into documents that read like a referral pack.
// Every document starts with a SYNTHETIC banner. No real patient data is used or accepted.

import type { DocKind, FactKey, FactValue, SourceDoc } from '../types';
import { PRIOR_AGENT_KEYS } from '../types';

export const SYNTHETIC_BANNER =
  'SYNTHETIC DOCUMENT — NOT A REAL PATIENT. Generated by Relay templates from hand-written facts for demonstration only.';

export interface GoldFact {
  key: FactKey;
  value: FactValue;
  unit?: string;
  refHigh?: number;
  observedOn?: string;
  doc: string;
}

export interface DocSpec {
  id: string;
  kind: DocKind;
  date: string;
  title?: string;
  initial: boolean;
  context?: Record<string, string>;
}

export interface Rendered {
  doc: SourceDoc;
  /** gold passage (one full line) for every fact key rendered in this document */
  passages: Partial<Record<FactKey, string>>;
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

export function longDate(iso: string): string {
  const [y, m, d] = iso.slice(0, 10).split('-').map((x) => parseInt(x, 10));
  return `${d} ${MONTHS[m - 1]} ${y}`;
}

export function parseLongDate(s: string): string | undefined {
  const m = /(\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})/.exec(s);
  if (!m) return undefined;
  const mm = String(MONTHS.indexOf(m[2]) + 1).padStart(2, '0');
  return `${m[3]}-${mm}-${m[1].padStart(2, '0')}`;
}

class Builder {
  lines: string[] = [];
  passages: Partial<Record<FactKey, string>> = {};
  add(line: string, keys: FactKey[] = []) {
    this.lines.push(line);
    for (const k of keys) this.passages[k] = line;
  }
  blank() {
    this.lines.push('');
  }
  text() {
    return this.lines.join('\n') + '\n';
  }
}

function header(b: Builder, title: string, patientId: string, dateLabel: string, date: string, extra: string[] = []) {
  b.add(SYNTHETIC_BANNER);
  b.add(title);
  b.add(`Patient: ${patientId} (synthetic)`);
  b.add(`${dateLabel}: ${longDate(date)}`);
  for (const e of extra) b.add(e);
  b.blank();
}

function get(facts: GoldFact[], key: FactKey): GoldFact | undefined {
  return facts.find((f) => f.key === key);
}

/// ---------------- referral summary ----------------

const HISTOLOGY_PHRASE: Record<string, string> = {
  nonsquamous_adenocarcinoma: 'Non-small cell lung cancer, adenocarcinoma (non-squamous), confirmed on CT-guided core biopsy.',
  squamous: 'Non-small cell lung cancer, squamous cell carcinoma, confirmed on bronchoscopic biopsy.',
  mixed_small_cell: 'Lung carcinoma with mixed histology including a small-cell component.',
};

const AGENT_NAME: Record<string, string> = {
  prior_platinum_chemo: 'platinum-based chemotherapy',
  prior_immunotherapy: 'anti-PD-1 immunotherapy',
  prior_kras_g12c_inhibitor: 'KRAS G12C inhibitor',
  prior_pan_ras_inhibitor: 'pan-RAS inhibitor',
  prior_docetaxel: 'docetaxel',
  prior_egfr_tki: 'EGFR tyrosine kinase inhibitor',
  prior_osimertinib: 'osimertinib',
  prior_alk_tki: 'ALK tyrosine kinase inhibitor',
  prior_her2_adc: 'HER2-directed antibody-drug conjugate',
  prior_anti_vegf: 'anti-VEGF therapy',
  prior_met_inhibitor: 'MET inhibitor',
  prior_zongertinib: 'zongertinib',
};

export const CNS_KEYS: FactKey[] = ['brain_mets', 'cns_symptomatic', 'cns_untreated', 'cns_progressing', 'leptomeningeal'];
export const INFECTION_KEYS: FactKey[] = ['hiv', 'hepatitis_active', 'tb_active', 'active_infection'];
export const MEDICINE_KEYS: FactKey[] = ['immunosuppressive_meds', 'qt_prolonging_meds', 'strong_cyp3a_meds', 'growth_factor_4w', 'recent_antibiotics', 'live_vaccine_recent'];
export const UNCERTAIN_HISTORY_KEYS: FactKey[] = [
  'prior_systemic_advanced',
  'prior_lines_advanced',
  ...PRIOR_AGENT_KEYS,
  'last_systemic_therapy_end',
  'adjuvant_therapy_end',
  'recovered_from_toxicity',
];
export const NO_PRIOR_THERAPY_KEYS: FactKey[] = ['prior_systemic_advanced', 'prior_lines_advanced', ...PRIOR_AGENT_KEYS, 'last_systemic_therapy_end', 'adjuvant_therapy_end'];

function brainPhrase(facts: GoldFact[]): string {
  const v = (k: FactKey) => get(facts, k)?.value;
  if (v('brain_mets') === 'none') return 'showed no intracranial metastases and no leptomeningeal disease.';
  const parts: string[] = [];
  parts.push(v('cns_untreated') === true ? 'two small untreated metastases (largest 6 mm)' : 'two metastases treated with stereotactic radiosurgery');
  parts.push(v('cns_progressing') === true ? 'enlarging since the previous scan' : 'stable compared with the previous scan');
  parts.push(v('leptomeningeal') === true ? 'leptomeningeal enhancement present' : 'no leptomeningeal disease');
  parts.push(v('cns_symptomatic') === true ? 'symptomatic with headaches, on dexamethasone' : 'neurologically asymptomatic and not on steroids');
  return `${parts.join('; ')}.`;
}

export function renderReferral(patientId: string, spec: DocSpec, all: GoldFact[]): Rendered {
  const facts = all.filter((f) => f.doc === spec.id);
  const has = (k: FactKey) => !!get(facts, k);
  const val = (k: FactKey) => get(facts, k)?.value;
  const keysPresent = (ks: FactKey[]) => ks.filter(has);
  const ctx = spec.context ?? {};
  const b = new Builder();
  header(b, 'Referral summary — Thoracic Oncology MDT (for clinical trial prescreening)', patientId, 'Date', spec.date, [
    `Referring team: ${ctx.referringTeam ?? 'Thoracic Oncology, District General Hospital (simulated)'}`,
  ]);

  if (has('age')) b.add(`Age: ${val('age')} years`, ['age']);
  if (ctx.sex) b.add(`Sex: ${ctx.sex}`);
  if (has('histology')) b.add(`Diagnosis: ${HISTOLOGY_PHRASE[String(val('histology'))]}`, ['histology']);
  else b.add('Diagnosis: Non-small cell lung cancer; histology as per the attached pathology report.');

  if (has('stage')) {
    const cur = val('curative_option') === 'not_amenable' ? 'not suitable for curative surgery or radical chemoradiotherapy' : 'curative-intent treatment under consideration';
    b.add(`Stage: ${val('stage')} (${ctx.tnm ?? 'cT2 N2 M1'}), ${cur}.`, keysPresent(['stage', 'curative_option']));
  }
  if (has('ecog')) b.add(`Performance status: ECOG ${val('ecog')} (assessed ${longDate(get(facts, 'ecog')!.observedOn ?? spec.date)}).`, ['ecog']);

  // Treatment history
  const prior = val('prior_systemic_advanced');
  if (prior === false) {
    b.add('Treatment history: No prior systemic anticancer therapy, including no neoadjuvant or adjuvant therapy.', keysPresent(NO_PRIOR_THERAPY_KEYS));
  } else if (prior === 'uncertain') {
    b.add(`Treatment history: ${ctx.uncertainNarrative ?? 'Reports a short course of tablets elsewhere; drug name and dates are not documented.'}`, keysPresent(UNCERTAIN_HISTORY_KEYS));
  } else if (prior === true) {
    b.add(`Treatment history: ${ctx.treatmentNarrative ?? 'Systemic therapy for advanced disease.'}`, ['prior_systemic_advanced']);
    if (has('prior_lines_advanced')) b.add(`Lines of systemic therapy for advanced disease: ${val('prior_lines_advanced')}.`, ['prior_lines_advanced']);
    const received = PRIOR_AGENT_KEYS.filter((k) => val(k) === true);
    const notReceived = PRIOR_AGENT_KEYS.filter((k) => val(k) === false);
    if (received.length) b.add(`Agents received: ${received.map((k) => AGENT_NAME[k]).join('; ')}.`, received);
    if (notReceived.length) b.add(`Agents not received: ${notReceived.map((k) => AGENT_NAME[k]).join('; ')}.`, notReceived);
    const last = val('last_systemic_therapy_end');
    if (typeof last === 'string' && /^\d{4}-/.test(last)) b.add(`Last dose of systemic anticancer therapy: ${longDate(last)}.`, ['last_systemic_therapy_end']);
    if (val('adjuvant_therapy_end') === 'none') b.add('Neoadjuvant/adjuvant therapy: None.', ['adjuvant_therapy_end']);
    if (has('recovered_from_toxicity')) {
      b.add(
        val('recovered_from_toxicity') === true ? 'Toxicity from prior therapy: Resolved to grade 1 or less.' : 'Toxicity from prior therapy: Ongoing grade 2 or higher toxicity.',
        ['recovered_from_toxicity'],
      );
    }
  }
  if (has('in_investigational_study')) {
    b.add(
      val('in_investigational_study') === false ? 'Clinical trials: Not in another study; no investigational treatment.' : 'Clinical trials: Currently in another interventional study.',
      ['in_investigational_study'],
    );
  }

  if (has('brain_mets')) {
    const when = longDate(get(facts, 'brain_mets')!.observedOn ?? spec.date);
    const sep = val('brain_mets') === 'none' ? ' ' : ': ';
    b.add(`Brain imaging: MRI brain on ${when}${sep}${brainPhrase(facts)}`, keysPresent(CNS_KEYS));
  }
  if (has('measurable_disease')) {
    const unirr = val('measurable_unirradiated') === true ? ', not previously irradiated' : '';
    b.add(
      val('measurable_disease') === true
        ? `Disease burden: Measurable disease per RECIST 1.1 (${ctx.lesion ?? 'primary lung mass 38 mm'})${unirr}.`
        : 'Disease burden: No measurable disease per RECIST 1.1.',
      keysPresent(['measurable_disease', 'measurable_unirradiated']),
    );
  }
  if (has('spinal_cord_compression')) {
    b.add(val('spinal_cord_compression') === 'none' ? 'Spinal cord: No spinal cord compression.' : 'Spinal cord: Cord compression treated with radiotherapy, stable.', ['spinal_cord_compression']);
  }

  b.blank();
  b.add('Medical history (prescreening checklist):');
  if (has('ild_history')) {
    b.add(val('ild_history') === false ? 'Lung history: No history of interstitial lung disease or pneumonitis.' : 'Lung history: History of drug-induced pneumonitis treated with steroids.', ['ild_history']);
  }
  if (has('ibd_history')) b.add(val('ibd_history') === false ? 'Bowel history: No history of inflammatory bowel disease.' : "Bowel history: History of Crohn's disease.", ['ibd_history']);
  if (has('gi_absorption_issue')) {
    b.add(
      val('gi_absorption_issue') === false
        ? 'Gastrointestinal: Swallows tablets; no condition affecting oral intake or absorption; no chronic diarrhoea.'
        : 'Gastrointestinal: Difficulty swallowing tablets after gastric surgery.',
      ['gi_absorption_issue'],
    );
  }
  if (has('cv_disease')) {
    const cv = val('cv_disease');
    const text =
      cv === 'none'
        ? 'No myocardial infarction, angina, arrhythmia, heart failure or stroke'
        : cv === 'controlled'
          ? (ctx.cardiovascular ?? 'Known cardiovascular disease, controlled')
          : 'Myocardial infarction within the last 6 months';
    const bp = val('uncontrolled_hypertension') === false ? '; blood pressure controlled' : '';
    b.add(`Cardiovascular: ${text}${bp}.`, keysPresent(['cv_disease', 'uncontrolled_hypertension']));
  }
  if (has('qtcf_ms')) b.add(`ECG on ${longDate(get(facts, 'qtcf_ms')!.observedOn ?? spec.date)}: QTcF ${val('qtcf_ms')} ms.`, ['qtcf_ms']);
  if (keysPresent(INFECTION_KEYS).length) {
    const parts = [
      `HIV ${val('hiv') === 'negative' ? 'negative' : 'positive'}`,
      val('hepatitis_active') === false ? 'no active hepatitis B or C' : 'active hepatitis B',
      val('tb_active') === false ? 'no active tuberculosis' : 'active tuberculosis',
      val('active_infection') === false ? 'no current infection needing systemic treatment' : 'current infection on intravenous antibiotics',
    ];
    b.add(`Infection screen: ${parts.join('; ')}.`, keysPresent(INFECTION_KEYS));
  }
  if (has('autoimmune_active')) b.add(val('autoimmune_active') === false ? 'Autoimmune disease: None.' : 'Autoimmune disease: Rheumatoid arthritis on methotrexate.', ['autoimmune_active']);
  if (has('transplant_history')) b.add(val('transplant_history') === false ? 'Transplant: None.' : 'Transplant: Kidney transplant 2015.', ['transplant_history']);
  if (has('other_malignancy')) b.add(val('other_malignancy') === 'none' ? 'Other cancers: None.' : 'Other cancers: Prostate cancer treated 2023.', ['other_malignancy']);
  if (has('uncontrolled_pain')) b.add(val('uncontrolled_pain') === false ? `Pain: ${ctx.pain ?? 'Controlled with paracetamol.'}` : 'Pain: Uncontrolled despite opioids.', ['uncontrolled_pain']);
  if (has('effusion_drainage')) b.add(val('effusion_drainage') === false ? 'Effusions: None needing drainage.' : 'Effusions: Pleural effusion drained every 2 weeks.', ['effusion_drainage']);
  if (has('major_surgery_recent')) b.add(val('major_surgery_recent') === false ? 'Surgery: No major surgery in the last 3 months.' : 'Surgery: Lobectomy 2 weeks ago.', ['major_surgery_recent']);
  if (has('last_radiotherapy')) {
    const rt = val('last_radiotherapy');
    b.add(rt === 'none' ? 'Radiotherapy: None.' : `Radiotherapy: ${ctx.radiotherapy ?? 'Radiotherapy'}, completed ${longDate(String(rt))}.`, ['last_radiotherapy']);
  }
  if (keysPresent(MEDICINE_KEYS).length) {
    b.add(
      `Current medicines: ${ctx.medicines ?? 'None regular.'} No immunosuppressants, QT-prolonging drugs, strong CYP3A inhibitors or inducers, haematopoietic growth factors, antibiotics or live vaccines in the last 4 weeks.`,
      keysPresent(MEDICINE_KEYS),
    );
  }
  if (has('pregnant_or_breastfeeding')) b.add('Pregnancy: Not pregnant or breastfeeding.', ['pregnant_or_breastfeeding']);
  if (has('tumour_sample_available')) {
    b.add(val('tumour_sample_available') === true ? 'Tumour tissue: Archival tumour block available.' : 'Tumour tissue: No tissue left after diagnostic testing.', ['tumour_sample_available']);
  }
  if (ctx.comorbidities) b.add(`Other medical history: ${ctx.comorbidities}`);
  b.blank();
  if (ctx.molecularStatus) b.add(`Molecular testing: ${ctx.molecularStatus}`);
  if (ctx.familyHistory) b.add(`Family history: ${ctx.familyHistory}`);
  b.add('Reason for referral: Prescreening for clinical trial options. Final eligibility rests with the study team.');

  return { doc: makeDoc(patientId, spec, spec.title ?? 'Referral summary', b.text()), passages: b.passages };
}

// ---------------- labs ----------------

export const LAB_ROWS: { key: FactKey; name: string }[] = [
  { key: 'lab_anc', name: 'Neutrophils' },
  { key: 'lab_hemoglobin', name: 'Haemoglobin' },
  { key: 'lab_platelets', name: 'Platelets' },
  { key: 'lab_bilirubin', name: 'Bilirubin' },
  { key: 'lab_alt', name: 'ALT' },
  { key: 'lab_ast', name: 'AST' },
  { key: 'lab_alp', name: 'Alkaline phosphatase' },
  { key: 'lab_creatinine', name: 'Creatinine' },
  { key: 'lab_egfr_renal', name: 'eGFR (CKD-EPI)' },
  { key: 'lab_inr', name: 'INR' },
];

const LAB_REF_LOW: Partial<Record<FactKey, number>> = {
  lab_anc: 2.0,
  lab_hemoglobin: 115,
  lab_platelets: 150,
  lab_bilirubin: 0,
  lab_alt: 0,
  lab_ast: 0,
  lab_alp: 30,
  lab_creatinine: 45,
  lab_inr: 0.8,
};

export function renderLabs(patientId: string, spec: DocSpec, all: GoldFact[]): Rendered {
  const facts = all.filter((f) => f.doc === spec.id);
  const b = new Builder();
  header(b, 'Blood results — Haematology and Clinical Biochemistry', patientId, 'Sample collected', spec.date, ['Requested by: Thoracic Oncology (simulated)']);
  for (const row of LAB_ROWS) {
    const f = get(facts, row.key);
    if (!f) continue;
    const ref = row.key === 'lab_egfr_renal' ? '>60' : `${LAB_REF_LOW[row.key]}–${f.refHigh}`;
    b.add(`${row.name}: ${f.value} ${f.unit} (reference ${ref})`, [row.key]);
  }
  b.blank();
  b.add('Comment: Results authorised by the laboratory (simulated).');
  return { doc: makeDoc(patientId, spec, spec.title ?? 'Blood results', b.text()), passages: b.passages };
}

// ---------------- pathology ----------------

export function renderPathology(patientId: string, spec: DocSpec, all: GoldFact[]): Rendered {
  const facts = all.filter((f) => f.doc === spec.id);
  const ctx = spec.context ?? {};
  const b = new Builder();
  header(b, 'Histopathology report', patientId, 'Report date', spec.date, [`Specimen: ${ctx.specimen ?? 'Bronchoscopic biopsy, left lower lobe'}`]);
  const hist = get(facts, 'histology');
  if (hist?.value === 'squamous') {
    b.add('Diagnosis: Squamous cell carcinoma of the lung (non-small cell lung carcinoma); tumour cells p40 positive, TTF-1 negative.', ['histology']);
  } else if (hist?.value === 'nonsquamous_adenocarcinoma') {
    b.add('Diagnosis: Adenocarcinoma of the lung (non-squamous non-small cell lung carcinoma); TTF-1 positive, p40 negative.', ['histology']);
  }
  const pdl1 = get(facts, 'pdl1_tps');
  if (pdl1) b.add(`PD-L1 (22C3) tumour proportion score (TPS): ${pdl1.value}%.`, ['pdl1_tps']);
  const notTested = facts.filter((f) => f.value === 'not_tested').map((f) => f.key);
  if (notTested.length) {
    b.add(`Molecular testing: Not performed — ${ctx.molecularNote ?? 'next-generation sequencing panel not requested at this stage.'}`, notTested);
  }
  return { doc: makeDoc(patientId, spec, spec.title ?? 'Histopathology report', b.text()), passages: b.passages };
}

// ---------------- molecular pathology (judge-settable) ----------------

export const MOLECULAR_OPTIONS = {
  kras: ['not_detected', 'G12C', 'G12D', 'G12V', 'G13D', 'Q61H'],
  nras: ['not_detected', 'Q61K', 'G12D'],
  hras: ['not_detected', 'Q61R'],
  egfr: ['not_detected', 'Ex19del', 'L858R', 'ex20ins', 'G719A', 'S768I', 'L861Q', 'E709K', 'T790M'],
  alk: ['not_detected', 'rearranged'],
  ros1: ['not_detected', 'rearranged'],
  braf: ['not_detected', 'V600E', 'G469A'],
  met: ['not_detected', 'exon14_skipping', 'amplification'],
  ret: ['not_detected', 'fusion'],
  her2: ['not_detected', 'mutation_tkd', 'mutation_non_tkd', 'amplification', 'overexpression'],
  nrg1: ['not_detected', 'fusion'],
} as const;

export interface MolecularReportInput {
  kras: string;
  egfr: string;
  alk: string;
  ros1: string;
  braf: string;
  met: string;
  ret: string;
  her2: string;
  pdl1Tps: number;
  reportDate: string; // ISO date
  nras?: string;
  hras?: string;
  nrg1?: string;
  patientId?: string;
  docId?: string;
}

/** SYN-0417 demo defaults: KRAS G12C, everything else not detected, PD-L1 TPS 0%. */
export const DEFAULT_DEMO_MOLECULAR: MolecularReportInput = {
  kras: 'G12C',
  egfr: 'not_detected',
  alk: 'not_detected',
  ros1: 'not_detected',
  braf: 'not_detected',
  met: 'not_detected',
  ret: 'not_detected',
  her2: 'not_detected',
  pdl1Tps: 0,
  reportDate: '2026-11-07',
  patientId: 'SYN-0417',
};

const KRAS_CDNA: Record<string, string> = { G12C: 'c.34G>T', G12D: 'c.35G>A', G12V: 'c.35G>T', G13D: 'c.38G>A', Q61H: 'c.183A>C' };

function pointLine(gene: string, v: string): string {
  if (v === 'not_detected') return `${gene}: no pathogenic variant detected.`;
  const cdna = gene === 'KRAS' && KRAS_CDNA[v] ? `${KRAS_CDNA[v]} ` : '';
  return `${gene}: ${cdna}p.(${v}) mutation detected.`;
}

function egfrLine(v: string): string {
  switch (v) {
    case 'not_detected':
      return 'EGFR: no pathogenic variant detected.';
    case 'Ex19del':
      return 'EGFR: exon 19 deletion p.(E746_A750del) detected.';
    case 'L858R':
      return 'EGFR: exon 21 p.(L858R) substitution detected.';
    case 'ex20ins':
      return 'EGFR: exon 20 insertion p.(A767_V769dup) detected.';
    default:
      return `EGFR: p.(${v}) mutation detected.`;
  }
}

function fusionLine(gene: string, partner: string, v: string): string {
  return v === 'not_detected' ? `${gene}: no fusion detected.` : `${gene}: ${partner}-${gene} fusion detected.`;
}

function metLine(v: string): string {
  const ex14 = v === 'exon14_skipping' ? 'exon 14 skipping variant detected' : 'no exon 14 skipping variant detected';
  const amp = v === 'amplification' ? 'amplification detected (estimated copy number 9)' : 'no amplification detected';
  return `MET: ${ex14}; ${amp}.`;
}

function her2Lines(v: string): { line: string; keys: FactKey[] }[] {
  const both: FactKey[] = ['her2_mutation', 'her2_amplification'];
  switch (v) {
    case 'not_detected':
      return [{ line: 'HER2 (ERBB2): no pathogenic variant or amplification detected.', keys: both }];
    case 'mutation_tkd':
      return [{ line: 'HER2 (ERBB2): exon 20 insertion p.(Y772_A775dup) detected (tyrosine kinase domain); no amplification detected.', keys: both }];
    case 'mutation_non_tkd':
      return [{ line: 'HER2 (ERBB2): p.(S310F) mutation detected (extracellular domain, outside the tyrosine kinase domain); no amplification detected.', keys: both }];
    case 'amplification':
      return [{ line: 'HER2 (ERBB2): no pathogenic variant detected; amplification detected.', keys: both }];
    case 'overexpression':
      return [
        { line: 'HER2 (ERBB2): no pathogenic variant or amplification detected.', keys: both },
        { line: 'HER2 protein (IHC): 3+ (overexpression).', keys: ['her2_overexpression'] },
      ];
    default:
      throw new Error(`unknown HER2 value ${v}`);
  }
}

function check(field: keyof typeof MOLECULAR_OPTIONS, v: string) {
  const allowed = MOLECULAR_OPTIONS[field] as readonly string[];
  if (!allowed.includes(v)) throw new Error(`makeMolecularReport: ${field}="${v}" is not one of ${allowed.join(', ')}`);
}

/**
 * Build a SYNTHETIC molecular pathology report from judge-set values. The returned passages map each
 * fact key to the exact line that states it (used as the gold passage in evaluation).
 */
export function makeMolecularReportWithPassages(input: MolecularReportInput): Rendered {
  const i = { nras: 'not_detected', hras: 'not_detected', nrg1: 'not_detected', ...input };
  (['kras', 'nras', 'hras', 'egfr', 'alk', 'ros1', 'braf', 'met', 'ret', 'her2', 'nrg1'] as const).forEach((k) => check(k, i[k]));
  if (typeof i.pdl1Tps !== 'number' || !Number.isFinite(i.pdl1Tps) || i.pdl1Tps < 0 || i.pdl1Tps > 100) {
    throw new Error('makeMolecularReport: pdl1Tps must be a number from 0 to 100 (decimals are kept as given, e.g. 0.5)');
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(i.reportDate)) throw new Error('makeMolecularReport: reportDate must be YYYY-MM-DD');
  const patientId = i.patientId ?? 'SYN-0417';
  const b = new Builder();
  header(b, 'Molecular pathology report — NGS panel (DNA and RNA) and PD-L1 immunohistochemistry', patientId, 'Report date', i.reportDate, [
    'Specimen: tumour tissue block (archival biopsy)',
    'Laboratory: Genomic Laboratory Hub (simulated)',
  ]);
  b.add('Accreditation: validated NGS assay; laboratory accredited to ISO 15189 (simulated).', ['molecular_lab_accredited']);
  b.add(pointLine('KRAS', i.kras), ['kras']);
  b.add(pointLine('NRAS', i.nras), ['nras']);
  b.add(pointLine('HRAS', i.hras), ['hras']);
  b.add(egfrLine(i.egfr), ['egfr']);
  b.add(fusionLine('ALK', 'EML4', i.alk), ['alk']);
  b.add(fusionLine('ROS1', 'CD74', i.ros1), ['ros1']);
  b.add(pointLine('BRAF', i.braf), ['braf']);
  b.add(metLine(i.met), ['met_ex14', 'met_amp']);
  b.add(fusionLine('RET', 'KIF5B', i.ret), ['ret']);
  for (const h of her2Lines(i.her2)) b.add(h.line, h.keys);
  b.add(fusionLine('NRG1', 'CD74', i.nrg1), ['nrg1']);
  b.add(`PD-L1 (22C3) tumour proportion score (TPS): ${i.pdl1Tps}%.`, ['pdl1_tps']);
  b.blank();
  b.add('Interpretation: for multidisciplinary team review. Variants reported against the laboratory panel (simulated).');
  const spec: DocSpec = { id: i.docId ?? `${patientId}-MOL-${i.reportDate.replace(/-/g, '')}`, kind: 'molecular', date: i.reportDate, initial: false };
  return { doc: makeDoc(patientId, spec, 'Molecular pathology report', b.text()), passages: b.passages };
}

export function makeMolecularReport(input: MolecularReportInput): SourceDoc {
  return makeMolecularReportWithPassages(input).doc;
}

/** Gold facts implied by a molecular report input (used by the synthetic data generator). */
export function molecularFacts(input: MolecularReportInput, docId: string): GoldFact[] {
  const i = { nras: 'not_detected', hras: 'not_detected', nrg1: 'not_detected', ...input };
  const at = i.reportDate;
  const f = (key: FactKey, value: FactValue, unit?: string): GoldFact => ({ key, value, doc: docId, observedOn: at, ...(unit ? { unit } : {}) });
  return [
    f('kras', i.kras),
    f('nras', i.nras),
    f('hras', i.hras),
    f('egfr', i.egfr),
    f('alk', i.alk),
    f('ros1', i.ros1),
    f('braf', i.braf),
    f('met_ex14', i.met === 'exon14_skipping' ? 'detected' : 'not_detected'),
    f('met_amp', i.met === 'amplification' ? 'detected' : 'not_detected'),
    f('ret', i.ret),
    f('her2_mutation', i.her2 === 'mutation_tkd' || i.her2 === 'mutation_non_tkd' ? i.her2 : 'not_detected'),
    f('her2_amplification', i.her2 === 'amplification' ? 'detected' : 'not_detected'),
    ...(i.her2 === 'overexpression' ? [f('her2_overexpression', 'ihc_3plus')] : []),
    f('nrg1', i.nrg1),
    f('pdl1_tps', i.pdl1Tps, '%'),
    f('molecular_lab_accredited', true),
  ];
}

function makeDoc(patientId: string, spec: DocSpec, title: string, text: string): SourceDoc {
  return { id: spec.id, patientId, kind: spec.kind, title, date: spec.date, version: 1, synthetic: true, text };
}

/** Guardrail: Relay only accepts documents that carry the SYNTHETIC banner. */
export function assertSynthetic(doc: SourceDoc): void {
  if (!doc || doc.synthetic !== true || !doc.text.startsWith('SYNTHETIC')) {
    throw new Error('Relay accepts synthetic documents only: the text must start with the SYNTHETIC banner and synthetic must be true. No real patient data, ever.');
  }
}
